gRe(){return"\u0418\u04d9. \u0422\u04e9\u043c\u0435\u043d \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u0430\u0493\u044b \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440 3.20 \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043d\u0456\u04a3 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0443\u044b\u043d\u0430\u043d \u0435\u0440\u0435\u043a\u0448\u0435\u043b\u0456\u043a \u0431\u043e\u043b\u044b\u043f \u0442\u0430\u0431\u044b\u043b\u0430\u0434\u044b. \u0411\u0430\u0441\u049b\u0430 \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0443\u043b\u0430\u0440 \u043c\u0435\u043d \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0440\u0434\u0456 \u0434\u0435 \u0435\u0441\u043a\u0435\u0440\u0443 \u049b\u0430\u0436\u0435\u0442."},
gRh(){return"\u0422\u0435\u043a 25 \u043a\u043c/\u0441\u0430\u0493 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u043f\u0435\u043d \u043a\u0435\u043b\u0435 \u0436\u0430\u0442\u049b\u0430\u043d \u049b\u0430\u0440\u0430\u043f\u0430\u0439\u044b\u043c \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u0493\u0430 \u0431\u043e\u043b\u0430 \u043c\u0430?"},
