ga2H(){return"\u041d\u0435 \u0434\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044c \u0440\u044f\u0434\u043e\u043c \u0441 \u043a\u0430\u0431\u0438\u043d\u043e\u0439 \u0438 \u0432\u043f\u043b\u043e\u0442\u043d\u0443\u044e \u0437\u0430 \u043f\u0440\u0438\u0446\u0435\u043f\u043e\u043c: \u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0433\u0440\u0443\u0437\u043e\u0432\u0438\u043a\u0430 \u043c\u043e\u0436\u0435\u0442 \u0432\u0430\u0441 \u043d\u0435 \u0432\u0438\u0434\u0435\u0442\u044c."},
ga2K(){return"\u0423 \u0437\u0435\u0431\u0440\u044b \u0442\u043e\u0440\u043c\u043e\u0437\u0438\u0442 \u0441\u043e\u0441\u0435\u0434 \u2014 \u0442\u043e\u0440\u043c\u043e\u0437\u0438\u0442\u0435"},
ga2J(){return"\u0422\u043e\u0436\u0435 \u0441\u043d\u0438\u0436\u0430\u0439\u0442\u0435 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0438\u043b\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435\u0441\u044c. \u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0439\u0442\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0432 \u043f\u0435\u0448\u0435\u0445\u043e\u0434\u043e\u0432."},
ga2M(){return"\u041d\u0435 \u043e\u0431\u044a\u0435\u0437\u0436\u0430\u0439\u0442\u0435 \u0444\u0443\u0440\u0443 \u0441\u043f\u0440\u0430\u0432\u0430 \u0443 \u043f\u043e\u0432\u043e\u0440\u043e\u0442\u0430"},
ga2L(){return"\u041f\u0440\u0438 \u043f\u0440\u0430\u0432\u043e\u043c \u043f\u043e\u0432\u043e\u0440\u043e\u0442\u0435 \u043f\u0440\u0438\u0446\u0435\u043f \u0441\u0440\u0435\u0437\u0430\u0435\u0442 \u0443\u0433\u043e\u043b. \u041d\u0435 \u0432\u044a\u0435\u0437\u0436\u0430\u0439\u0442\u0435 \u0432 \u0437\u0430\u0437\u043e\u0440 \u043c\u0435\u0436\u0434\u0443 \u0433\u0440\u0443\u0437\u043e\u0432\u0438\u043a\u043e\u043c \u0438 \u0431\u043e\u0440\u0434\u044e\u0440\u043e\u043c."},
ga2O(){return"\u0417\u0430\u043f\u043e\u0442\u0435\u043b\u043e \u0441\u0442\u0435\u043a\u043b\u043e \u2014 \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u043e\u0431\u0434\u0443\u0432"},
ga2N(){return"\u041d\u0430\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u0432\u043e\u0437\u0434\u0443\u0445 \u043d\u0430 \u043b\u043e\u0431\u043e\u0432\u043e\u0435 \u0441\u0442\u0435\u043a\u043b\u043e, \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u043a\u043e\u043d\u0434\u0438\u0446\u0438\u043e\u043d\u0435\u0440 \u0438 \u043e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0440\u0435\u0446\u0438\u0440\u043a\u0443\u043b\u044f\u0446\u0438\u044e."},
ga2Q(){return"\u041d\u0430 \u0443\u043a\u043b\u043e\u043d\u0435 \u0437\u0430\u043a\u0440\u0435\u043f\u0438\u0442\u0435 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u044c"},
ga2P(){return"\u0421\u0442\u043e\u044f\u043d\u043e\u0447\u043d\u044b\u0439 \u0442\u043e\u0440\u043c\u043e\u0437 + \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u0438\u043b\u0438 P. \u0423 \u043f\u0440\u0430\u0432\u043e\u0433\u043e \u0431\u043e\u0440\u0434\u044e\u0440\u0430: \u043d\u0430 \u0441\u043f\u0443\u0441\u043a\u0435 \u043a\u043e\u043b\u0451\u0441\u0430 \u043a \u043d\u0435\u043c\u0443, \u043d\u0430 \u043f\u043e\u0434\u044a\u0451\u043c\u0435 \u2014 \u043e\u0442 \u043d\u0435\u0433\u043e."},
ga2S(){return"\u0412 \u0442\u0443\u043c\u0430\u043d\u0435 \u0432\u044b\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0434\u0430\u043b\u044c\u043d\u0438\u0439"},
ga2R(){return"\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0431\u043b\u0438\u0436\u043d\u0438\u0439, \u0441\u043d\u0438\u0437\u044c\u0442\u0435 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u044c\u0442\u0435 \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u044e. \u041f\u0440\u043e\u0442\u0438\u0432\u043e\u0442\u0443\u043c\u0430\u043d\u043a\u0438 \u0432\u044b\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435, \u043a\u043e\u0433\u0434\u0430 \u0432\u0438\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u0443\u043b\u0443\u0447\u0448\u0438\u0442\u0441\u044f."},
ga2U(){return"\u0410\u0432\u0430\u0440\u0438\u0439\u043d\u044b\u0439 \u0437\u043d\u0430\u043a: \u043c\u0438\u043d\u0438\u043c\u0443\u043c 15 \u0438\u043b\u0438 30 \u043c"},
ga2T(){return"\u0412 \u043d\u0430\u0441\u0435\u043b\u0451\u043d\u043d\u043e\u043c \u043f\u0443\u043d\u043a\u0442\u0435 \u2014 \u043e\u0442 15 \u043c, \u0432\u043d\u0435 \u0435\u0433\u043e \u2014 \u043e\u0442 30 \u043c. \u041f\u0440\u0438 \u043f\u043b\u043e\u0445\u043e\u0439 \u0432\u0438\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0434\u0430\u043b\u044c\u0448\u0435."},
