ga2X(){return"\u041e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435\u0441\u044c \u0432 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u043c \u043c\u0435\u0441\u0442\u0435 \u0438 \u043f\u043e\u0441\u043f\u0438\u0442\u0435. \u041f\u043b\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u0445\u043e\u0442\u044f \u0431\u044b 15 \u043c\u0438\u043d\u0443\u0442 \u043e\u0442\u0434\u044b\u0445\u0430 \u043a\u0430\u0436\u0434\u044b\u0435 2 \u0447\u0430\u0441\u0430."},
gFY(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c"},
gPz(){return"\u0421\u044b\u0433\u0440\u0430\u0439\u0442\u0435, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043f\u0430\u0441\u0442\u044c \u0432 \u0440\u0435\u0439\u0442\u0438\u043d\u0433"},
gPC(){return"\u0412\u043e\u0439\u0434\u0438\u0442\u0435 \u0432 \u0430\u043a\u043a\u0430\u0443\u043d\u0442, \u0447\u0442\u043e\u0431\u044b \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0432 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0435"},
a0b(a){return"\u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442: **"+a+"**"},
gKv(){return"\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0439"},
ga0h(){return"\u0414\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0432\u043e\u043f\u0440\u043e\u0441\u0430 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0439 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442."},
ga0l(){return"\u041a\u0430\u043a\u043e\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0432 \u044d\u0442\u043e\u043c \u0432\u043e\u043f\u0440\u043e\u0441\u0435?"},
ga0m(){return"\u041f\u043e\u0447\u0435\u043c\u0443 \u0432\u0435\u0440\u0435\u043d \u0438\u043c\u0435\u043d\u043d\u043e \u044d\u0442\u043e\u0442 \u043e\u0442\u0432\u0435\u0442?"},
