ga0j(){return"\u0414\u043b\u044f \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u0432 \u0418\u0418 \u0432\u043e\u0439\u0434\u0438\u0442\u0435 \u0432 \u0430\u043a\u043a\u0430\u0443\u043d\u0442. \u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0431\u0435\u0437 \u0432\u0445\u043e\u0434\u0430."},
gKw(){return"\u0414\u043d\u0435\u0432\u043d\u043e\u0439 \u043b\u0438\u043c\u0438\u0442 \u0418\u0418 \u0438\u0441\u0447\u0435\u0440\u043f\u0430\u043d. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u043f\u043e\u0441\u043b\u0435 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u043b\u0438\u043c\u0438\u0442\u0430."},
gVt(){return"\u0417\u0430\u0435\u0437\u0434\u044b \u0432 \xab\u0416\u0438\u0432\u043e\u043c \u0433\u043e\u0440\u043e\u0434\u0435\xbb \u0431\u0435\u0437 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f"},
ga6U(){return"\u0414\u0430\u043d\u043d\u044b\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430 \u0443\u0434\u0430\u043b\u0435\u043d\u044b. \u0414\u043b\u044f \u0441\u0442\u0430\u0440\u043e\u0433\u043e \u0432\u0445\u043e\u0434\u0430 \u0447\u0435\u0440\u0435\u0437 Apple \u0442\u0430\u043a\u0436\u0435 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 Apple Account \u2192 \xab\u0412\u0445\u043e\u0434 \u0441 Apple\xbb, \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0438 \u043f\u0440\u0435\u043a\u0440\u0430\u0442\u0438\u0442\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 Apple ID."},
ga6T(){return"\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 Apple Account"},
gKx(){return"\u0418\u0418 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u043f\u043e\u0437\u0436\u0435."},
ON(a){return"\u041d\u0443\u0436\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u044d\u0442\u0443 \u043e\u043f\u043b\u0430\u0442\u0443. \u041d\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \xab\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u2192 \u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430\xbb \u0438 \u0443\u043a\u0430\u0436\u0438\u0442\u0435 \u043d\u043e\u043c\u0435\u0440 \u0437\u0430\u043a\u0430\u0437\u0430: "+a},
OM(a){return"\u0417\u0430\u043f\u0440\u043e\u0441 \u043e\u043f\u043b\u0430\u0442\u044b \u0435\u0449\u0451 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f. \u041d\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e. \u0417\u0430\u043a\u0430\u0437: "+a+". \u0415\u0441\u043b\u0438 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u043e\u043f\u043b\u0430\u0442\u044b \u043d\u0435 \u043e\u0442\u043a\u0440\u044b\u043b\u0430\u0441\u044c, \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c \u0432 \xab\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u2192 \u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430\xbb."},
ga6V(){return"\u0414\u0430\u043d\u043d\u044b\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430 \u0443\u0434\u0430\u043b\u0435\u043d\u044b. \u0417\u0430\u043f\u0440\u043e\u0441 \u043d\u0430 \u043e\u0442\u0437\u044b\u0432 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 Apple \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d. \u041c\u044b \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043c \u043e\u0442\u0437\u044b\u0432 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438, \u043a\u043e\u0433\u0434\u0430 \u0441\u0435\u0440\u0432\u0438\u0441 Apple \u0441\u043d\u043e\u0432\u0430 \u0441\u0442\u0430\u043d\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d."},
AQ(a){return"\u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442: "+a},
gOX(){return"\u0414\u0435\u0442\u0430\u043b\u0438 \u043e\u0442\u0432\u0435\u0442\u0430"},
